<script lang="ts">
 import {onMount,onDestroy,tick,createEventDispatcher} from 'svelte';
 import {resolveMentions} from './resolve-mentions';
 import ChatImageChips from './ChatImageChips.svelte';
 import type {ChatImageDraft} from './chat-images';
 export let images:ChatImageDraft[]=[];
 $: imagePending=images.some(image=>image.status!=='ready');
 export let people:any[]=[];export let bots:any[]=[];export let currentRoom:any=null;export let draft='';export let accessSignal:AbortSignal;
 export let disabled=false;export let busy=false;export let working=false;export let stopping=false;export let placeholder='Write a message…';
 type Range={start:number;end:number;kind:'human'|'agent';id:string;label:string};
 export let mentionRanges:Range[]=[];
 const dispatch=createEventDispatcher();let textarea:HTMLTextAreaElement,caret=0,composing=false,focused=false,activeIndex=0,error='',lastDraft='',roomId='',mounted=false,seenSignal:AbortSignal,detach=()=>{},dismissed='';
 let ranges:Range[]=[];let blocked=false;
 $: directory=[...people.map(p=>({...p,kind:'human' as const})),...bots.map(b=>({...b,kind:'agent' as const}))].filter(p=>typeof p.id==='string'&&!!p.id&&typeof p.name==='string'&&!!p.name.trim());
 $: query=focused&&!composing&&!disabled&&!busy&&!blocked?findQuery(draft,caret,ranges):null;
 $: signature=query?query.start+':'+query.query:'';
 $: suggestions=query&&signature!==dismissed?directory.filter((p,i,a)=>a.findIndex(v=>v.id===p.id&&v.kind===p.kind)===i&&(p.name+' '+(p.role||'')+' '+(p.email||'')).toLocaleLowerCase().includes(query.query.toLocaleLowerCase())).slice(0,8):[];
 $: if(activeIndex>=suggestions.length)activeIndex=0;
 $: listId='mention-options-'+encodeURIComponent(currentRoom?.id||'empty');
 $: if(mounted&&(roomId!==(currentRoom?.id||'')||seenSignal!==accessSignal))resetScope();
 $: if(mounted&&draft!==lastDraft){ranges=shiftRanges(lastDraft,draft,ranges);lastDraft=draft;}
 function known(range:Range,text=draft){return Number.isInteger(range.start)&&Number.isInteger(range.end)&&range.start>=0&&range.end<=text.length&&range.end>range.start&&text.slice(range.start,range.end)==='@'+range.label&&(range.start===0||/[\s([{]/.test(text[range.start-1]))&&(range.end===text.length||/[\s.,!?;:)\]}]/.test(text[range.end]))&&directory.some(p=>p.id===range.id&&p.kind===range.kind&&p.name===range.label);}
 $: resolvedMentions=resolveMentions(draft,directory,ranges.filter(r=>known(r)));
 function selected(){return resolvedMentions;}
 function findQuery(text:string,position:number,tokens:Range[]){if(position<0||position>text.length)return null;const before=text.slice(0,position),match=/(?:^|[\s([{])@([^\n@]{0,80})$/.exec(before);if(!match)return null;const start=position-match[1].length-1;if(tokens.some(r=>r.start===start&&position>=r.end))return null;return {start,end:position,query:match[1]};}
 function shiftRanges(before:string,after:string,tokens:Range[]){if(before===after)return tokens;let prefix=0;while(prefix<before.length&&prefix<after.length&&before[prefix]===after[prefix])prefix++;let suffix=0;while(suffix<before.length-prefix&&suffix<after.length-prefix&&before[before.length-1-suffix]===after[after.length-1-suffix])suffix++;const removedEnd=before.length-suffix,delta=after.length-before.length;return tokens.flatMap(r=>{if(r.end<=prefix)return [r];if(r.start>=removedEnd)return [{...r,start:r.start+delta,end:r.end+delta}];return [];}).filter(r=>r.start>=0&&r.end<=after.length&&after.slice(r.start,r.end)==='@'+r.label);}
 function emitDraft(){dispatch('draft',{roomId,draft,mentions:selected(),mentionRanges:ranges.filter(r=>known(r)).map(r=>({...r}))});}
 function pasted(event:ClipboardEvent){if(disabled||busy||blocked||!currentRoom?.id)return;const files=Array.from(event.clipboardData?.items||[]).filter(item=>item.kind==='file'&&item.type.startsWith('image/')).map(item=>item.getAsFile()).filter((file):file is File=>!!file);if(files.length){if(!event.clipboardData?.getData('text/plain'))event.preventDefault();dispatch('images',{roomId:currentRoom.id,files});}}
 function resize(){if(textarea){textarea.style.height='auto';textarea.style.height=Math.min(170,Math.max(54,textarea.scrollHeight))+'px';}}
 function input(e:Event){const input=e.currentTarget as HTMLTextAreaElement,next=input.value;ranges=shiftRanges(lastDraft,next,ranges);draft=lastDraft=next;caret=input.selectionStart;activeIndex=0;dismissed='';error='';emitDraft();resize();}
 function cursor(){if(textarea)caret=textarea.selectionStart;}
 async function choose(person:any){if(!query||disabled||busy)return;const target=query,label='@'+person.name,old=draft,next=old.slice(0,target.start)+label+' '+old.slice(target.end);ranges=shiftRanges(old,next,ranges).filter(r=>r.end<=target.start||r.start>=target.start+label.length);ranges=[...ranges,{start:target.start,end:target.start+label.length,kind:person.kind,id:person.id,label:person.name}];draft=lastDraft=next;caret=target.start+label.length+1;dismissed='';activeIndex=0;emitDraft();await tick();textarea?.focus();textarea?.setSelectionRange(caret,caret);resize();}
 function send(){if(disabled||busy||working||!currentRoom?.id||imagePending||!draft.trim()&&!images.length||accessSignal?.aborted)return;const mentions=selected();if(mentions.filter(m=>m.kind==='agent').length>16){error='A message supports up to 16 bot mentions.';return;}if(mentions.length>32){error='A message supports up to 32 mentions.';return;}dispatch('send',{roomId:currentRoom.id,draft,content:draft.trim(),mentions,dispatchAgentIds:mentions.filter(m=>m.kind==='agent').map(m=>m.id),mentionRanges:ranges.filter(r=>known(r)).map(r=>({...r}))});}
 function keydown(e:KeyboardEvent){if(e.isComposing||composing)return;if(suggestions.length&&query&&signature!==dismissed){if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();activeIndex=(activeIndex+(e.key==='ArrowDown'?1:-1)+suggestions.length)%suggestions.length;return;}if((e.key==='Enter'&&!e.shiftKey)||e.key==='Tab'){e.preventDefault();void choose(suggestions[activeIndex]);return;}if(e.key==='Escape'){e.preventDefault();dismissed=signature;return;}}if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();send();}}
 function resetScope(){detach();blocked=false;ranges=[];lastDraft=draft;roomId=currentRoom?.id||'';seenSignal=accessSignal;caret=0;error='';dismissed='';ranges=mentionRanges.filter(r=>known(r)).map(r=>({...r}));const signal=accessSignal;const clear=()=>{blocked=true;ranges=[];draft=lastDraft='';focused=false;error='';dispatch('draft',{roomId,draft:'',mentions:[],mentionRanges:[]});};signal?.addEventListener('abort',clear,{once:true});detach=()=>signal?.removeEventListener('abort',clear);if(signal?.aborted)clear();void tick().then(resize);}
 onMount(()=>{mounted=true;});onDestroy(()=>{detach();ranges=[];focused=false;});
</script>
<div class="mention-composer">
 {#if suggestions.length&&signature!==dismissed}<div class="mention-menu" role="listbox" id={listId} aria-label="Mention someone">{#each suggestions as person,i(person.kind+person.id)}<button id={listId+'-'+i} type="button" role="option" aria-selected={activeIndex===i} class:active={activeIndex===i} on:mousedown|preventDefault on:mouseenter={()=>activeIndex=i} on:click={()=>choose(person)}><span class="avatar" class:bot={person.kind==='agent'}>{person.name.slice(0,1)}</span><span><strong>{person.name}</strong><small>{person.kind==='agent'?'Company bot':person.role||'Company member'}{person.email?' · '+person.email:''}</small></span><span class="type">{person.kind==='agent'?'Bot':'Person'}</span></button>{/each}<footer>↑ ↓ to select · Enter to mention · Esc to close</footer></div>{/if}
 <div class="composer" class:blocked={disabled||blocked}><ChatImageChips {images} {busy} on:remove={event=>dispatch('removeimage',event.detail)}/><textarea bind:this={textarea} value={draft} {placeholder} aria-label="Message" role="combobox" aria-autocomplete="list" aria-expanded={suggestions.length>0&&signature!==dismissed} aria-controls={listId} aria-activedescendant={suggestions.length&&signature!==dismissed?listId+'-'+activeIndex:undefined} disabled={disabled||blocked||busy||!currentRoom?.id} rows="2" on:paste={pasted} on:input={input} on:keydown={keydown} on:keyup={cursor} on:click={cursor} on:select={cursor} on:focus={()=>{focused=true;cursor();}} on:blur={()=>focused=false} on:compositionstart={()=>composing=true} on:compositionend={()=>{composing=false;cursor();}}/><div class="composer-footer"><div class="actions"><slot name="tools"/><button type="button" class="mention-trigger" aria-label="Mention a person or bot" disabled={disabled||busy||!currentRoom?.id} on:click={async()=>{if(!textarea)return;textarea.focus();const position=textarea.selectionStart,next=draft.slice(0,position)+(position&&!/\s/.test(draft[position-1])?' @':'@')+draft.slice(textarea.selectionEnd);const at=next.length-(draft.length-textarea.selectionEnd);ranges=shiftRanges(draft,next,ranges);draft=lastDraft=next;caret=at;dismissed='';focused=true;emitDraft();await tick();textarea.setSelectionRange(at,at);}}>＠</button></div>{#if working}<button type="button" class="stop" disabled={disabled||blocked||stopping} on:click={()=>dispatch('stop',{roomId})}>{stopping?'Stopping all…':'■ Stop all'}</button>{:else}<button type="button" class="send" aria-label="Send message" disabled={disabled||busy||imagePending||!currentRoom?.id||!draft.trim()&&!images.length} on:click={send}>{busy?'…':'↑'}</button>{/if}</div></div>{#if resolvedMentions.length}<p class="mention-summary" role="status">{resolvedMentions.filter(m=>m.kind==='agent').length} bot mentions · {resolvedMentions.filter(m=>m.kind==='human').length} people mentions</p>{/if}{#if error}<p class="error" role="alert">{error}</p>{/if}
</div>
<style>.mention-composer{position:relative;width:100%;color:#17243f}.composer{border:1px solid #e6ebf4;border-radius:13px;background:#fff;padding:13px 15px 10px;box-shadow:0 3px 13px #17243f04}.composer.blocked{background:#fafbfd}textarea,button{font:inherit}textarea{display:block;width:100%;border:0;outline:none;resize:none;min-height:54px;max-height:170px;background:none;font-size:12px;line-height:1.75;color:#34415a;padding:0}textarea::placeholder{color:#a8b2c3}.composer-footer{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-top:5px}.actions{display:flex;align-items:center;gap:7px}.mention-trigger{background:none;border:0;color:#97a5bc;font-size:19px;padding:0 4px;line-height:27px}.send{width:30px;height:29px;border:0;border-radius:7px;background:#3466f6;color:white;font-size:21px;line-height:1}.stop{background:#eff3ff;color:#6d8ac9;border:0;border-radius:7px;padding:6px 10px;font-size:11px}button{cursor:pointer}button:disabled{opacity:.45;cursor:default}.mention-menu{position:absolute;bottom:calc(100% + 8px);left:0;width:min(420px,100%);border:1px solid #e6ebf4;border-radius:12px;box-shadow:0 12px 40px #17243f15;background:#fff;padding:6px;z-index:30;max-height:340px;overflow:auto}.mention-menu>button{display:flex;align-items:center;gap:10px;width:100%;text-align:left;border:0;border-radius:7px;background:none;padding:10px;color:#17243f}.mention-menu>button.active{background:#edf3ff}.avatar{display:grid;place-items:center;width:28px;height:28px;border-radius:7px;background:#f0f3f8;color:#8a99af;font-size:11px;flex:none}.avatar.bot{border-radius:50%;background:radial-gradient(circle at 25% 25%,#d9efff,#7ca5de 60%,#b19bdc);color:#fff}.mention-menu strong{font-size:12px;font-weight:550;display:block}.mention-menu small{font-size:10px;color:#9ba8bc;display:block;overflow-wrap:anywhere}.type{font-size:9px;color:#a6b2c3;margin-left:auto;white-space:nowrap}.mention-menu footer{font-size:9px;color:#a8b3c4;padding:9px 11px 5px;border-top:1px solid #f0f3f8;margin-top:4px}.error{font-size:11px;color:#af5960;margin:8px 0;line-height:1.6}button:focus-visible,textarea:focus-visible{outline:2px solid #8aabff;outline-offset:3px}@media(max-width:600px){.mention-menu{max-height:260px}.mention-menu footer{font-size:8px}.composer{padding:11px 12px 9px}}.mention-summary{font-size:10px;color:#64748b;margin:7px 3px 0}
</style>
